/* Offline Deterministic LaTeX-to-HTML Renderer (KaTeX-compatible API, Zero CDN) */
(function (global) {
  "use strict";

  var SYMBOLS = {
    "\\cdot": " &middot; ",
    "\\times": " &times; ",
    "\\leq": " &le; ",
    "\\le": " &le; ",
    "\\geq": " &ge; ",
    "\\ge": " &ge; ",
    "\\neq": " &ne; ",
    "\\pm": " &plusmn; ",
    "\\approx": " &asymp; ",
    "\\phi": "&phi;",
    "\\Phi": "&Phi;",
    "\\Omega": "&Omega;",
    "\\Delta": "&Delta;",
    "\\delta": "&delta;",
    "\\theta": "&theta;",
    "\\lambda": "&lambda;",
    "\\alpha": "&alpha;",
    "\\beta": "&beta;",
    "\\gamma": "&gamma;",
    "\\psi": "&psi;",
    "\\epsilon": "&epsilon;",
    "\\sigma": "&sigma;",
    "\\tau": "&tau;",
    "\\pi": "&pi;",
    "\\mu": "&mu;",
    "\\rho": "&rho;",
    "\\parallel": "&#8741;",
    "\\perp": "&perp;",
    "\\circ": "&deg;",
    "\\ell": "&#8467;",
    "\\prime": "&prime;",
    "\\sum": "&sum;",
    "\\min": "min",
    "\\max": "max"
  };

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function readBraced(src, pos) {
    if (pos >= src.length || src.charAt(pos) !== "{") {
      return null;
    }
    var depth = 0;
    for (var i = pos; i < src.length; i++) {
      var ch = src.charAt(i);
      if (ch === "{") depth++;
      else if (ch === "}") {
        depth--;
        if (depth === 0) {
          return { content: src.slice(pos + 1, i), next: i + 1 };
        }
      }
    }
    return null;
  }

  function readAtom(src, pos) {
    while (pos < src.length && src.charAt(pos) === " ") pos++;
    if (pos >= src.length) return { html: "", next: pos };
    if (src.charAt(pos) === "{") {
      var blk = readBraced(src, pos);
      if (blk) return { html: parseSegment(blk.content), next: blk.next };
    }
    if (src.charAt(pos) === "\\") {
      var m = src.slice(pos).match(/^\\[A-Za-z]+/);
      if (m) {
        var cmd = m[0];
        if (SYMBOLS[cmd]) return { html: SYMBOLS[cmd], next: pos + cmd.length };
        return { html: escapeHtml(cmd.slice(1)), next: pos + cmd.length };
      }
    }
    return { html: escapeHtml(src.charAt(pos)), next: pos + 1 };
  }

  function parseSegment(src) {
    var out = "";
    var i = 0;
    while (i < src.length) {
      var ch = src.charAt(i);
      if (src.slice(i, i + 5) === "\\left") {
        i += 5;
        continue;
      }
      if (src.slice(i, i + 6) === "\\right") {
        i += 6;
        continue;
      }
      if (src.slice(i, i + 5) === "\\frac") {
        var num = readBraced(src, i + 5);
        if (num) {
          var den = readBraced(src, num.next);
          if (den) {
            out += '<span class="mfrac"><span class="num">' + parseSegment(num.content) +
                   '</span><span class="den">' + parseSegment(den.content) + "</span></span>";
            i = den.next;
            continue;
          }
        }
      }
      if (src.slice(i, i + 5) === "\\sqrt") {
        var rad = readBraced(src, i + 5);
        if (rad) {
          out += '<span class="sqrt"><span class="sqrt-sign">&radic;</span><span class="sqrt-body">' +
                 parseSegment(rad.content) + "</span></span>";
          i = rad.next;
          continue;
        }
      }
      if (src.slice(i, i + 5) === "\\text" || src.slice(i, i + 7) === "\\mathrm") {
        var offset = src.slice(i, i + 5) === "\\text" ? 5 : 7;
        var txt = readBraced(src, i + offset);
        if (txt) {
          out += '<span class="mtext">' + escapeHtml(txt.content) + "</span>";
          i = txt.next;
          continue;
        }
      }
      if (ch === "_") {
        var sub = readAtom(src, i + 1);
        out += "<sub>" + sub.html + "</sub>";
        i = sub.next;
        continue;
      }
      if (ch === "^") {
        var sup = readAtom(src, i + 1);
        out += "<sup>" + sup.html + "</sup>";
        i = sup.next;
        continue;
      }
      if (ch === "\\") {
        var cmdMatch = src.slice(i).match(/^\\[A-Za-z]+/);
        if (cmdMatch) {
          var sym = cmdMatch[0];
          out += SYMBOLS[sym] !== undefined ? SYMBOLS[sym] : escapeHtml(sym.slice(1));
          i += sym.length;
          continue;
        }
      }
      if (ch === "{" || ch === "}") {
        i++;
        continue;
      }
      out += escapeHtml(ch);
      i++;
    }
    return out;
  }

  function renderToString(expr, options) {
    var inner = parseSegment(String(expr || ""));
    var displayMode = options && options.displayMode;
    var cls = displayMode ? "katex katex-display" : "katex";
    return '<span class="' + cls + '">' + inner + "</span>";
  }

  function render(expr, element, options) {
    if (element) {
      element.innerHTML = renderToString(expr, options);
    }
  }

  global.katex = {
    version: "0.16.9-offline",
    renderToString: renderToString,
    render: render
  };
})(typeof window !== "undefined" ? window : this);
